//! Signing with a key held in memory, the way FE-speed's wallet-server signs with a WIF
//! (`utils/crypto.util.ts`: `signPsbtRawtTx` and `signRawTransction`, bitcoinjs-lib 6.0.1).
//!
//! The page never sees the key: it holds a `tlk1:` handle ([`crate::legacy::keyvault`]) and the
//! service resolves it here after its guards ran. Semantics are bitcoinjs's, reproduced for the
//! script types FE-speed uses and checked byte for byte against its own functions
//! (`fespeed_sign_kat.json`, regenerated by `scripts/gen-fespeed-sign-kat.cjs`):
//!
//! * `sign_psbt`: `signAllInputs` (every input the key can sign, `SIGHASH_ALL`, an input that
//!   cannot be signed is skipped, none signed is `No inputs were signed`), then
//!   `finalizeAllInputs` + `extractTransaction`. `psbtHex` is the PSBT right after signing;
//!   `isFinished` and `finalHex` come from the finalised transaction, and a finalisation or fee
//!   check failure (`>= 5000 sat/vB`) is `isFinished: false`.
//! * `sign_tx`: FE-speed rebuilds a PSBT from the caller's inputs (a single-key input is
//!   P2SH-P2WPKH of the key, an input with a multisig script is P2SH-P2WSH of it), signs every
//!   input, requires a signature on each (`No signatures to validate`), and answers the
//!   extracted transaction, or the PSBT hex when it cannot be finalised.
//!
//! Differences from FE-speed, all refusals or fixes: the rebuilt PSBT keeps the raw
//! transaction's version, locktime and input sequences (FE-speed replaced them with 2, 0 and
//! `0xffffffff`), inputs are signed in the transaction's order, and an input whose
//! `scriptPubKey` is not the P2SH form the key would spend is refused instead of producing a
//! transaction the network rejects.

use bitcoin::ecdsa::Signature as BtcSignature;
use bitcoin::hashes::{hash160, sha256, Hash};
use bitcoin::hex::{DisplayHex, FromHex};
use bitcoin::opcodes::all::OP_CHECKMULTISIG;
use bitcoin::psbt::Psbt;
use bitcoin::script::{Builder, Instruction, PushBytesBuf};
use bitcoin::secp256k1::{All, Message, PublicKey as SecpPublicKey, Secp256k1};
use bitcoin::sighash::{EcdsaSighashType, SighashCache};
use bitcoin::{Amount, OutPoint, PublicKey, Script, ScriptBuf, Transaction, TxOut, Witness};
use serde_json::{json, Value};
use tl_wallet_service::psbt::decode_tx;
use tl_wallet_service::txbuilder::Utxo;

use super::keyvault::LocalKey;

/// bitcoinjs `Psbt` default `maximumFeeRate` (sat/vB): `extractTransaction` refuses at or above.
const MAX_FEE_RATE: u64 = 5000;
const MAX_PSBT_HEX_CHARS: usize = 400_000;

type R<T> = Result<T, String>;

/// `signPsbtRawtTx`: the answer is `{psbtHex, isValid, isFinished, finalHex?}`.
pub fn sign_psbt(secp: &Secp256k1<All>, key: &LocalKey, psbt_hex: &str) -> R<Value> {
    if psbt_hex.len() > MAX_PSBT_HEX_CHARS {
        return Err("psbtHex too large".into());
    }
    let bytes = Vec::<u8>::from_hex(psbt_hex).map_err(|_| "psbtHex malformed".to_string())?;
    let mut psbt = Psbt::deserialize(&bytes).map_err(|e| format!("psbt: {e}"))?;
    sign_all_inputs(secp, &mut psbt, key)?;
    let signed_hex = psbt.serialize().to_lower_hex_string();
    let mut out = json!({ "psbtHex": signed_hex, "isValid": true, "isFinished": false });
    if let Ok(final_hex) = finalize_all(&mut psbt).and_then(|()| extract(&psbt)) {
        out["isFinished"] = json!(true);
        out["finalHex"] = json!(final_hex);
    }
    Ok(out)
}

/// `signRawTransction`: the answer is `{signedHex, isValid, isFinished}`.
pub fn sign_tx(secp: &Secp256k1<All>, key: &LocalKey, rawtx: &str, inputs: &[Utxo]) -> R<Value> {
    let tx = decode_tx(rawtx).map_err(|e| e.to_string())?;
    let mut psbt = Psbt::from_unsigned_tx(tx)
        .map_err(|_| "Format Error: Transaction ScriptSigs are not empty".to_string())?;
    let key_program = ScriptBuf::new_p2wpkh(&key.compressed().wpubkey_hash());
    for i in 0..psbt.inputs.len() {
        let prev = psbt.unsigned_tx.input[i].previous_output;
        let u = find_input(inputs, &prev)
            .ok_or_else(|| format!("input {i} is not among the inputs"))?;
        let amount = Amount::from_sat(u.amount.sat());
        let (program, witness_script) = match &u.redeem_script {
            Some(rs) => {
                let ws = ScriptBuf::from_bytes(
                    Vec::<u8>::from_hex(rs)
                        .map_err(|_| "input.redeemScript malformed".to_string())?,
                );
                parse_multisig(&ws).ok_or("input.redeemScript is not a multisig script")?;
                (ScriptBuf::new_p2wsh(&ws.wscript_hash()), Some(ws))
            }
            None => (key_program.clone(), None),
        };
        if !u.script_pub_key.is_empty() {
            let spk = Vec::<u8>::from_hex(&u.script_pub_key)
                .map_err(|_| "input.scriptPubKey malformed".to_string())?;
            if spk != ScriptBuf::new_p2sh(&program.script_hash()).as_bytes() {
                return Err(format!(
                    "input {i}: scriptPubKey is not the P2SH address this key spends"
                ));
            }
        }
        let pi = &mut psbt.inputs[i];
        pi.witness_utxo = Some(TxOut {
            value: amount,
            script_pubkey: program.clone(),
        });
        pi.redeem_script = Some(program);
        pi.witness_script = witness_script;
    }
    sign_all_inputs(secp, &mut psbt, key)?;
    if psbt.inputs.iter().any(|i| i.partial_sigs.is_empty()) {
        return Err("No signatures to validate".into());
    }
    let finished = finalize_all(&mut psbt).and_then(|()| extract(&psbt));
    Ok(match finished {
        Ok(hex) => json!({ "signedHex": hex, "isValid": true, "isFinished": true }),
        Err(_) => json!({
            "signedHex": psbt.serialize().to_lower_hex_string(),
            "isValid": true,
            "isFinished": false,
        }),
    })
}

fn find_input<'a>(inputs: &'a [Utxo], op: &OutPoint) -> Option<&'a Utxo> {
    let id = op.txid.to_string();
    inputs
        .iter()
        .find(|u| u.vout == op.vout && u.txid.eq_ignore_ascii_case(&id))
}

// ------------------------------------------------------------------ signing

/// `signAllInputs`: every input that can be signed gets a signature; none at all is an error.
fn sign_all_inputs(secp: &Secp256k1<All>, psbt: &mut Psbt, key: &LocalKey) -> R<()> {
    let mut any = false;
    for i in 0..psbt.inputs.len() {
        if sign_input(secp, psbt, i, key).is_ok() {
            any = true;
        }
    }
    if any {
        Ok(())
    } else {
        Err("No inputs were signed".into())
    }
}

/// How bitcoinjs's `getMeaningfulScript` reads an input.
enum Kind {
    P2wsh(ScriptBuf),
    P2wpkh(ScriptBuf),
}

fn meaningful(spk: &Script, redeem: Option<&Script>, witness: Option<&Script>) -> R<Kind> {
    let is_p2sh = spk.is_p2sh();
    let is_p2sh_p2wsh = is_p2sh && redeem.is_some_and(Script::is_p2wsh);
    let is_p2wsh = spk.is_p2wsh();
    if is_p2sh && redeem.is_none() {
        return Err("scriptPubkey is P2SH but redeemScript missing".into());
    }
    if (is_p2wsh || is_p2sh_p2wsh) && witness.is_none() {
        return Err("scriptPubkey or redeemScript is P2WSH but witnessScript missing".into());
    }
    let script: ScriptBuf = if is_p2sh_p2wsh {
        let (rs, ws) = (
            redeem.ok_or("redeemScript missing")?,
            witness.ok_or("witnessScript missing")?,
        );
        check_hash160(spk, rs)?;
        check_sha256(rs, ws)?;
        ws.to_owned()
    } else if is_p2wsh {
        let ws = witness.ok_or("witnessScript missing")?;
        check_sha256(spk, ws)?;
        ws.to_owned()
    } else if is_p2sh {
        let rs = redeem.ok_or("redeemScript missing")?;
        check_hash160(spk, rs)?;
        rs.to_owned()
    } else {
        spk.to_owned()
    };
    if is_p2wsh || is_p2sh_p2wsh {
        if script.is_p2wpkh() || script.is_p2sh() {
            return Err("P2WPKH or P2SH can not be contained within P2WSH".into());
        }
        Ok(Kind::P2wsh(script))
    } else if script.is_p2wpkh() {
        Ok(Kind::P2wpkh(script))
    } else {
        Err("only witness v0 inputs are signed".into())
    }
}

fn check_hash160(spk: &Script, redeem: &Script) -> R<()> {
    let h = hash160::Hash::hash(redeem.as_bytes());
    if spk.as_bytes().get(2..22) == Some(&h.to_byte_array()[..]) {
        Ok(())
    } else {
        Err("redeem script does not match the scriptPubKey".into())
    }
}

fn check_sha256(spk_or_redeem: &Script, witness: &Script) -> R<()> {
    let h = sha256::Hash::hash(witness.as_bytes());
    if spk_or_redeem.as_bytes().get(2..34) == Some(&h.to_byte_array()[..]) {
        Ok(())
    } else {
        Err("witness script does not match the program".into())
    }
}

/// bitcoinjs `pubkeyInScript`: the key, or its hash160, appears as a push.
fn pubkey_in_script(pk: &PublicKey, script: &Script) -> bool {
    let key = pk.to_bytes();
    let hash = hash160::Hash::hash(&key).to_byte_array();
    script.instructions().flatten().any(|ins| match ins {
        Instruction::PushBytes(p) => p.as_bytes() == key.as_slice() || p.as_bytes() == hash,
        Instruction::Op(_) => false,
    })
}

fn sign_input(secp: &Secp256k1<All>, psbt: &mut Psbt, i: usize, key: &LocalKey) -> R<()> {
    let input = &psbt.inputs[i];
    if input.final_script_sig.is_some() || input.final_script_witness.is_some() {
        return Err("input is finalised".into());
    }
    let hash_type = match input.sighash_type {
        None => EcdsaSighashType::All,
        Some(t) => match t.ecdsa_hash_ty() {
            Ok(EcdsaSighashType::All) => EcdsaSighashType::All,
            _ => return Err("Sighash type is not allowed".into()),
        },
    };
    let prevout = input
        .witness_utxo
        .as_ref()
        .ok_or("Need a Utxo input item for signing")?;
    let kind = meaningful(
        &prevout.script_pubkey,
        input.redeem_script.as_deref(),
        input.witness_script.as_deref(),
    )?;
    let pubkey = key.bitcoin_pubkey();
    if input.partial_sigs.contains_key(&pubkey) {
        return Err("Can not add duplicate data to array".into());
    }
    let mut cache = SighashCache::new(&psbt.unsigned_tx);
    let digest = match &kind {
        Kind::P2wsh(ws) => {
            if !pubkey_in_script(&pubkey, ws) {
                return Err("Can not sign for this input with the key".into());
            }
            cache
                .p2wsh_signature_hash(i, ws, prevout.value, hash_type)
                .map_err(|e| e.to_string())?
                .to_byte_array()
        }
        Kind::P2wpkh(program) => {
            if !pubkey_in_script(&pubkey, program) {
                return Err("Can not sign for this input with the key".into());
            }
            cache
                .p2wpkh_signature_hash(i, program, prevout.value, hash_type)
                .map_err(|e| e.to_string())?
                .to_byte_array()
        }
    };
    let sig = key.sign_digest(secp, &Message::from_digest(digest));
    psbt.inputs[i].partial_sigs.insert(
        pubkey,
        BtcSignature {
            signature: sig,
            sighash_type: hash_type,
        },
    );
    Ok(())
}

// ------------------------------------------------------------------ finalising

/// `(m, pubkeys)` of a bare `OP_m <pubkeys> OP_n OP_CHECKMULTISIG` script (bitcoinjs `p2ms`).
fn parse_multisig(script: &Script) -> Option<(usize, Vec<SecpPublicKey>)> {
    let ins: Vec<Instruction> = script.instructions().collect::<Result<_, _>>().ok()?;
    let num = |i: &Instruction| match i {
        Instruction::Op(op) => {
            let b = op.to_u8();
            (0x51..=0x60).contains(&b).then(|| usize::from(b - 0x50))
        }
        Instruction::PushBytes(_) => None,
    };
    let (first, rest) = ins.split_first()?;
    let (last, rest) = rest.split_last()?;
    let (n_ins, keys) = rest.split_last()?;
    if !matches!(last, Instruction::Op(op) if *op == OP_CHECKMULTISIG) {
        return None;
    }
    let (m, n) = (num(first)?, num(n_ins)?);
    let mut pubkeys = Vec::with_capacity(keys.len());
    for k in keys {
        match k {
            Instruction::PushBytes(p) => {
                pubkeys.push(SecpPublicKey::from_slice(p.as_bytes()).ok()?)
            }
            Instruction::Op(_) => return None,
        }
    }
    (pubkeys.len() == n && m <= n && n >= 1).then_some((m, pubkeys))
}

/// `finalizeAllInputs`: stops at the first input that cannot be finalised.
fn finalize_all(psbt: &mut Psbt) -> R<()> {
    for i in 0..psbt.inputs.len() {
        finalize_input(psbt, i)?;
    }
    Ok(())
}

fn push_script(script: &Script) -> R<ScriptBuf> {
    let data = PushBytesBuf::try_from(script.as_bytes().to_vec())
        .map_err(|_| "script too large".to_string())?;
    Ok(Builder::new().push_slice(&data).into_script())
}

fn finalize_input(psbt: &mut Psbt, i: usize) -> R<()> {
    let input = &psbt.inputs[i];
    let prev_spk = input.witness_utxo.as_ref().map(|o| o.script_pubkey.clone());
    // bitcoinjs getScriptFromInput
    let is_p2sh = input.redeem_script.is_some();
    let is_p2wsh = input.witness_script.is_some();
    let script = input
        .witness_script
        .clone()
        .or_else(|| input.redeem_script.clone())
        .or(prev_spk)
        .ok_or_else(|| format!("No script found for input #{i}"))?;
    let is_segwit = is_p2wsh || script.is_p2wpkh();
    if !is_segwit {
        return Err(format!("Can not finalize input #{i}"));
    }
    let can = || format!("Can not finalize input #{i}");
    let mut stack: Vec<Vec<u8>> = Vec::new();
    if script.is_p2wpkh() {
        if input.partial_sigs.len() > 1 {
            return Err("Too many signatures".into());
        }
        let (pk, sig) = input.partial_sigs.iter().next().ok_or_else(can)?;
        if script.as_bytes().get(2..22)
            != Some(&hash160::Hash::hash(&pk.to_bytes()).to_byte_array()[..])
        {
            return Err("Pubkey mismatch".into());
        }
        stack.push(sig.to_vec());
        stack.push(pk.to_bytes());
    } else {
        let (m, pubkeys) = parse_multisig(&script).ok_or_else(can)?;
        let mut sigs: Vec<Vec<u8>> = Vec::new();
        for pk in &pubkeys {
            let compressed = PublicKey::new(*pk);
            if let Some(sig) = input.partial_sigs.get(&compressed) {
                sigs.push(sig.to_vec());
            }
        }
        if sigs.len() > m {
            return Err("Too many signatures".into());
        }
        if sigs.len() != m {
            return Err(can());
        }
        stack.push(Vec::new());
        stack.extend(sigs);
        stack.push(script.to_bytes());
    }
    let mut final_script_sig = None;
    if is_p2wsh {
        // witness: [OP_0, sigs..., witnessScript]; the script sig of a wrapped one pushes the program
        let ws = input.witness_script.as_ref().ok_or_else(can)?;
        if is_p2sh {
            final_script_sig = Some(push_script(&ScriptBuf::new_p2wsh(&ws.wscript_hash()))?);
        }
    } else if is_p2sh {
        final_script_sig = Some(push_script(&script)?);
    }
    let pi = &mut psbt.inputs[i];
    pi.final_script_sig = final_script_sig;
    pi.final_script_witness = Some(Witness::from_slice(&stack));
    // clearFinalizedInput keeps only the UTXOs, the final scripts and unknown fields
    pi.partial_sigs.clear();
    pi.sighash_type = None;
    pi.redeem_script = None;
    pi.witness_script = None;
    pi.bip32_derivation.clear();
    Ok(())
}

/// `extractTransaction()` with bitcoinjs's default fee check.
fn extract(psbt: &Psbt) -> R<String> {
    let mut tx: Transaction = psbt.unsigned_tx.clone();
    let mut total_in: u64 = 0;
    for (i, input) in psbt.inputs.iter().enumerate() {
        if input.final_script_sig.is_none() && input.final_script_witness.is_none() {
            return Err("Not finalized".into());
        }
        if let Some(s) = &input.final_script_sig {
            tx.input[i].script_sig = s.clone();
        }
        if let Some(w) = &input.final_script_witness {
            tx.input[i].witness = w.clone();
        }
        let value = match (&input.witness_utxo, &input.non_witness_utxo) {
            (Some(o), _) => o.value.to_sat(),
            (None, Some(prev)) => prev
                .output
                .get(tx.input[i].previous_output.vout as usize)
                .map_or(0, |o| o.value.to_sat()),
            (None, None) => 0,
        };
        total_in = total_in.saturating_add(value);
    }
    let total_out: u64 = tx.output.iter().map(|o| o.value.to_sat()).sum();
    let fee = total_in
        .checked_sub(total_out)
        .ok_or("Outputs are spending more than Inputs")?;
    let vsize = tx.vsize() as u64;
    if fee / vsize.max(1) >= MAX_FEE_RATE {
        return Err("fee rate above the maximum".into());
    }
    Ok(bitcoin::consensus::encode::serialize_hex(&tx))
}

